extends Node
class_name TrafficCoordinator

@export var intersection_radius := 5.0
@export var reservation_timeout := 4.0
@export var min_vehicle_gap := 5.5
@export var signal_phase_seconds := 14.0
@export var signal_all_red_seconds := 1.5
@export var signal_yellow_seconds := 2.5
@export var waiting_queue_timeout := 3.0
@export var intersection_clearance_margin := 2.5

var intersections: Array[Vector3] = []
var reservations: Dictionary = {}
var waiting_queues: Dictionary = {}
var waiting_axes: Dictionary = {}
var waiting_ttls: Dictionary = {}
var traffic_vehicles: Array = []
var signal_elapsed := 0.0

func configure_from_road_graph(graph) -> void:
    intersections.clear()
    reservations.clear()
    waiting_queues.clear()
    waiting_axes.clear()
    waiting_ttls.clear()

    if graph == null:
        return

    for i in range(graph.nodes.size()):
        var degree: int = int(graph.adjacency.get(i, []).size())
        if degree >= 3:
            intersections.append(graph.nodes[i])

func register_vehicle(vehicle) -> void:
    if vehicle == null:
        return
    if vehicle not in traffic_vehicles:
        traffic_vehicles.append(vehicle)

func unregister_vehicle(vehicle) -> void:
    if vehicle == null:
        return

    traffic_vehicles.erase(vehicle)

    var vehicle_id: int = vehicle.get_instance_id()
    for key in reservations.keys():
        var reservation: Dictionary = reservations[key]
        if int(reservation.get("owner", -1)) == vehicle_id:
            reservations.erase(key)
    _remove_vehicle_from_waiting_queues(vehicle_id)

func _process(delta: float) -> void:
    _tick_waiting_queues(delta)
    signal_elapsed = fmod(signal_elapsed + maxf(delta, 0.0), maxf(signal_phase_seconds * 2.0, 0.1))
    for key in reservations.keys().duplicate():
        var reservation: Dictionary = reservations[key]
        reservation["ttl"] = float(reservation.get("ttl", 0.0)) - delta

        if float(reservation["ttl"]) <= 0.0:
            reservations.erase(key)
        else:
            reservations[key] = reservation


func current_signal_state() -> Dictionary:
    var phase_seconds: float = maxf(signal_phase_seconds, 0.1)
    var yellow_seconds: float = clampf(signal_yellow_seconds, 0.0, phase_seconds)
    var all_red_seconds: float = clampf(signal_all_red_seconds, 0.0, maxf(phase_seconds - yellow_seconds, 0.0))
    var green_seconds: float = maxf(phase_seconds - yellow_seconds - all_red_seconds, 0.0)
    var local_time: float = fmod(signal_elapsed, phase_seconds)
    var active_axis: int = int(floor(signal_elapsed / phase_seconds)) % 2
    if local_time < green_seconds:
        return {"axis": active_axis, "state": "green"}
    if local_time < green_seconds + yellow_seconds:
        return {"axis": active_axis, "state": "yellow"}
    return {"axis": -1, "state": "all_red"}

func current_green_axis() -> int:
    var signal_state: Dictionary = current_signal_state()
    if str(signal_state.get("state", "all_red")) != "green":
        return -1
    return int(signal_state.get("axis", -1))

func signal_allows_approach(intersection_index: int, approach_direction: Vector3) -> bool:
    if intersection_index < 0:
        return true
    var green_axis: int = current_green_axis()
    if green_axis < 0:
        return false
    if approach_direction.length_squared() <= 0.0001:
        return false
    var direction := approach_direction.normalized()
    var approach_axis := 0 if absf(direction.x) >= absf(direction.z) else 1
    return approach_axis == green_axis

func pedestrian_allows_crossing(intersection_index: int, crossing_direction: Vector3) -> bool:
    if intersection_index < 0:
        return true
    var green_axis: int = current_green_axis()
    if green_axis < 0:
        return false
    if crossing_direction.length_squared() <= 0.0001:
        return false
    var direction := crossing_direction.normalized()
    var crossing_axis := 0 if absf(direction.x) >= absf(direction.z) else 1
    if crossing_axis != green_axis:
        return false
    if reservations.has(intersection_index):
        var reservation: Dictionary = reservations[intersection_index]
        var vehicle_axis: int = int(reservation.get("axis", -1))
        if vehicle_axis >= 0 and vehicle_axis != crossing_axis:
            return false
    return true


func vehicle_inside_intersection(vehicle, intersection_index: int) -> bool:
    if vehicle == null or intersection_index < 0 or intersection_index >= intersections.size():
        return false
    var center: Vector3 = intersections[intersection_index]
    var offset := Vector2(vehicle.global_position.x - center.x, vehicle.global_position.z - center.z)
    return offset.length_squared() <= intersection_radius * intersection_radius

func vehicle_has_cleared_intersection(vehicle, intersection_index: int) -> bool:
    if vehicle == null or intersection_index < 0 or intersection_index >= intersections.size():
        return false
    var center: Vector3 = intersections[intersection_index]
    var offset := Vector2(vehicle.global_position.x - center.x, vehicle.global_position.z - center.z)
    var clearance_radius := maxf(intersection_radius + intersection_clearance_margin, intersection_radius)
    return offset.length_squared() > clearance_radius * clearance_radius

func nearest_intersection_index(position: Vector3) -> int:
    var best: int = -1
    var best_distance: float = float(intersection_radius * intersection_radius)

    for i in range(intersections.size()):
        var distance: float = position.distance_squared_to(intersections[i])
        if distance <= best_distance:
            best_distance = distance
            best = i

    return best

func queue_for_intersection(vehicle, intersection_index: int, approach_direction := Vector3.ZERO) -> void:
    if vehicle == null or intersection_index < 0:
        return
    var vehicle_id: int = vehicle.get_instance_id()
    var queue: Array = waiting_queues.get(intersection_index, [])
    if vehicle_id not in queue:
        queue.append(vehicle_id)
        waiting_queues[intersection_index] = queue
    var key: String = _waiting_key(intersection_index, vehicle_id)
    waiting_axes[key] = _approach_axis(approach_direction)
    waiting_ttls[key] = maxf(waiting_queue_timeout, 0.1)

func request_intersection(vehicle, intersection_index: int, approach_direction := Vector3.ZERO) -> bool:
    if vehicle == null:
        return false
    if intersection_index < 0:
        return true

    var vehicle_id: int = vehicle.get_instance_id()
    if reservations.has(intersection_index):
        var reservation: Dictionary = reservations[intersection_index]
        if int(reservation.get("owner", -1)) == vehicle_id:
            reservation["ttl"] = reservation_timeout
            reservations[intersection_index] = reservation
            return true
        return false

    queue_for_intersection(vehicle, intersection_index, approach_direction)
    _prune_waiting_queue(intersection_index)
    var queue: Array = waiting_queues.get(intersection_index, [])
    var approach_axis: int = _approach_axis(approach_direction)
    if approach_axis < 0:
        return false
    var eligible_vehicle_id: int = _first_waiting_vehicle_for_axis(intersection_index, approach_axis)
    if eligible_vehicle_id < 0 or eligible_vehicle_id != vehicle_id:
        return false
    if not signal_allows_approach(intersection_index, approach_direction):
        return false

    reservations[intersection_index] = {
        "owner": vehicle_id,
        "ttl": reservation_timeout,
        "axis": approach_axis
    }
    queue.erase(vehicle_id)
    if queue.is_empty():
        waiting_queues.erase(intersection_index)
    else:
        waiting_queues[intersection_index] = queue
    var waiting_key := _waiting_key(intersection_index, vehicle_id)
    waiting_axes.erase(waiting_key)
    waiting_ttls.erase(waiting_key)
    return true

func _first_waiting_vehicle_for_axis(intersection_index: int, approach_axis: int) -> int:
    if intersection_index < 0 or approach_axis < 0:
        return -1
    _prune_waiting_queue(intersection_index)
    var queue: Array = waiting_queues.get(intersection_index, [])
    for queued_id in queue:
        var vehicle_id: int = int(queued_id)
        var queued_axis: int = int(waiting_axes.get(_waiting_key(intersection_index, vehicle_id), -1))
        if queued_axis == approach_axis:
            return vehicle_id
    return -1

func waiting_position(vehicle, intersection_index: int) -> int:
    if vehicle == null or intersection_index < 0:
        return -1
    _prune_waiting_queue(intersection_index)
    var queue: Array = waiting_queues.get(intersection_index, [])
    return queue.find(vehicle.get_instance_id())


func _tick_waiting_queues(delta: float) -> void:
    var step := maxf(delta, 0.0)
    for key_value in waiting_ttls.keys().duplicate():
        var key: String = str(key_value)
        var ttl: float = float(waiting_ttls.get(key, 0.0)) - step
        if ttl > 0.0:
            waiting_ttls[key] = ttl
            continue
        waiting_ttls.erase(key)
        waiting_axes.erase(key)
        var parts: PackedStringArray = key.split(":", false, 1)
        if parts.size() != 2:
            continue
        var intersection_index: int = int(parts[0])
        var vehicle_id: int = int(parts[1])
        if not waiting_queues.has(intersection_index):
            continue
        var queue: Array = waiting_queues[intersection_index]
        queue.erase(vehicle_id)
        if queue.is_empty():
            waiting_queues.erase(intersection_index)
        else:
            waiting_queues[intersection_index] = queue

func _approach_axis(approach_direction: Vector3) -> int:
    if approach_direction.length_squared() <= 0.0001:
        return -1
    var direction: Vector3 = approach_direction.normalized()
    return 0 if absf(direction.x) >= absf(direction.z) else 1

func _waiting_key(intersection_index: int, vehicle_id: int) -> String:
    return "%d:%d" % [intersection_index, vehicle_id]

func _remove_vehicle_from_waiting_queues(vehicle_id: int) -> void:
    for intersection_index in waiting_queues.keys().duplicate():
        var queue: Array = waiting_queues[intersection_index]
        queue.erase(vehicle_id)
        var key := _waiting_key(int(intersection_index), vehicle_id)
        waiting_axes.erase(key)
        waiting_ttls.erase(key)
        if queue.is_empty():
            waiting_queues.erase(intersection_index)
        else:
            waiting_queues[intersection_index] = queue

func _prune_waiting_queue(intersection_index: int) -> void:
    if not waiting_queues.has(intersection_index):
        return
    var queue: Array = waiting_queues[intersection_index]
    var active_ids: Dictionary = {}
    for registered_vehicle in traffic_vehicles:
        if registered_vehicle != null and is_instance_valid(registered_vehicle):
            active_ids[registered_vehicle.get_instance_id()] = true
    var cleaned: Array = []
    for queued_id in queue:
        var vehicle_id: int = int(queued_id)
        if active_ids.has(vehicle_id):
            cleaned.append(vehicle_id)
        else:
            var key: String = _waiting_key(intersection_index, vehicle_id)
            waiting_axes.erase(key)
            waiting_ttls.erase(key)
    if cleaned.is_empty():
        waiting_queues.erase(intersection_index)
    else:
        waiting_queues[intersection_index] = cleaned

func release_intersection(vehicle, intersection_index: int) -> void:
    if vehicle == null:
        return
    if intersection_index < 0:
        return
    if not reservations.has(intersection_index):
        return

    var reservation: Dictionary = reservations[intersection_index]
    if int(reservation.get("owner", -1)) == vehicle.get_instance_id():
        reservations.erase(intersection_index)

func has_front_gap(vehicle, forward: Vector3) -> bool:
    if vehicle == null:
        return true

    for other in traffic_vehicles:
        if other == null:
            continue
        if other == vehicle:
            continue
        if not is_instance_valid(other):
            continue

        var delta_position: Vector3 = other.global_position - vehicle.global_position
        var distance: float = delta_position.length()

        if distance <= 0.01:
            continue
        if distance > min_vehicle_gap:
            continue

        var alignment: float = forward.normalized().dot(delta_position.normalized())
        if alignment > 0.55:
            return false

    return true
